-- ============================================================================
-- Statement Studio V2 -- PRODUCTION CATALOG IMPORT.
--
-- DATA IMPORT, NOT A MIGRATION. It creates no table, column, constraint,
-- index, policy or function in public, and changes no grant. It inserts 63
-- requirement sets and 80 requirement documents and nothing else.
--
-- GENERATED by scripts/build_statement_requirements_import_sql.py from the
-- validated dry-run previews. Do not hand-edit: rebuild it. A human editing
-- 143 rows of verbatim school prose is the failure this generation exists to
-- prevent.
--
-- SOURCE FINGERPRINTS (SHA-256). The reviewed files are the files executed:
--   06_IMPORT_programs.csv                       75ce2e3cec2989608fa0cbb4884bec64923cc96c5ba920ce3b7e3f94edc0bdd4
--   07_IMPORT_documents.csv                      9a4158a137f0183f088263bf0c87f7f54d9d149ce3f23e17be6d363841f9f476
--   10_school_id_reconciliation.csv              709b1203dfd7f216710cc0946aa6eca32f57b6c2a0eeb4cd53548f6f8a91a39b
--   11_statement_requirement_sets_preview.csv    aedb965ba83172329fe14e4a79322ac1adbcb9de4f5452b4e81b183c92fb8979
--   12_statement_requirements_preview.csv        10ba99d9c8c9c067dcba88677c4d83f88741c7fda7f08504aa6654cb7c8ac9e4
--
-- ============================================================================
-- WHY THE IDS ARE DERIVED HERE AND NOT BY THE DATABASE.
-- ============================================================================
-- Every id below is a UUIDv5 of a fixed namespace plus a stable name:
--
--   a set:      crnaprephub:statement_requirement_set:<research slug>
--   a document: crnaprephub:statement_requirement:<research slug>:<index>
--
-- so rebuilding this file from the same previews produces byte-identical ids.
--
-- THE DECIDING FACT IS THAT NEITHER CATALOG TABLE HAS A UNIQUE CONSTRAINT
-- OTHER THAN ITS PRIMARY KEY. 005 declares `id uuid primary key default
-- gen_random_uuid()` and nothing else unique -- no unique on school_id, none
-- on (school_id, application_cycle). So with database-generated ids, running
-- this file twice would insert a SECOND COMPLETE CATALOG with no error at
-- all, and every applicant would see every school twice. With the ids fixed
-- here, a second run dies on
--
--   duplicate key value violates unique constraint
--     "statement_requirement_sets_pkey"
--
-- inside the transaction, inserting nothing. The safety is the primary key
-- doing its job, which only works if WE choose the key.
--
-- It also makes an uncertain execution DECIDABLE. The ids are known before
-- the run, so counting how many of them exist afterwards distinguishes "not
-- applied" (0) from "fully applied" (143) from "something else happened"
-- (anything between). A gen_random_uuid() import leaves no such question to
-- ask. See statement_requirements_catalog_import_postcheck.sql.
--
-- RECOMMENDED FOLLOW-UP, OUT OF SCOPE HERE: a unique constraint on the
-- catalog would make this structural rather than conventional. That is a
-- schema migration and this file is not one.
--
-- ============================================================================
-- HOW IT FAILS
-- ============================================================================
-- One transaction. The payload is staged in TEMP tables first, so every
-- precondition -- including whether each school_id exists in public.schools
-- and whether a held-back programme crept in -- is checked BEFORE a single
-- row reaches the catalog. All failures are collected and reported together
-- rather than one at a time.
--
-- THERE IS NO `on conflict` ANYWHERE IN THIS FILE, deliberately. `do nothing`
-- would convert "the catalog is already there" -- the one state that must
-- stop everything -- into a silent success.
--
-- NOTHING IS ACTIVATED. Every set is inserted is_active = false, so the
-- catalog is invisible to applicants even with STATEMENT_REQUIREMENTS on.
-- Activation is a separate decision and a separate statement.
-- ============================================================================

begin;

-- Fail fast rather than queue behind a long transaction. The catalog tables
-- are empty and unread, so this should never wait at all.
set local lock_timeout = '5s';
set local statement_timeout = '120s';

-- ---- staging ------------------------------------------------------------
create temp table _import_sets (
  id                         uuid,
  school_id                  uuid,
  application_cycle          text,
  verification_status        text,
  source_url                 text,
  verified_on                date,
  is_verbatim                boolean,
  original_text              text,
  notes                      jsonb,
  is_active                  boolean,
  display_order              integer
) on commit drop;

create temp table _import_docs (
  id                         uuid,
  set_id                     uuid,
  school_id                  uuid,
  document_type              text,
  label                      text,
  prompt_text                text,
  components                 jsonb,
  min_words                  integer,
  max_words                  integer,
  min_characters             integer,
  max_characters             integer,
  characters_include_spaces  boolean,
  min_pages                  numeric(4,1),
  max_pages                  numeric(4,1),
  page_spacing               text,
  font_size_pt               integer,
  font_family                text,
  margins_inches             numeric(4,2),
  citation_style             text,
  citation_family            text,
  min_references             integer,
  other_instructions         jsonb,
  choice_group               text,
  is_optional                boolean,
  notes                      jsonb,
  is_active                  boolean,
  display_order              integer,
  words_enforcement          text,
  words_stated_as            text,
  characters_enforcement     text,
  characters_stated_as       text,
  pages_enforcement          text,
  pages_stated_as            text,
  unenforced_length          text,
  unenforced_length_verbatim boolean
) on commit drop;

create temp table _held_back (
  slug                       text,
  school_id                  uuid
) on commit drop;

insert into _import_sets (id, school_id, application_cycle, verification_status, source_url, verified_on, is_verbatim, original_text, notes, is_active, display_order) values
