  ('dcd90900-8db5-5b7f-ba01-28ab9823cd2e'::uuid, '6b9f3678-565f-4213-9cd1-7e5003d4e3a1'::uuid, null, 'verified', 'https://www.uwlax.edu/academics/grad/nurse-anesthesia/application-process/', '2026-10-02'::date, true, 'ONE personal statement, typed and double-spaced, "less than two pages in length", addressing SIX required areas. The instruction says applicants "will need to address each of the following areas" — all six are required, not a selection.', '[]'::jsonb, false, 0),
