  ('a8482c8f-c8dd-5150-8e9f-12fb3326db46'::uuid, '9c752371-5d30-5789-84a9-32b47d638495'::uuid, '0df89478-37a5-4d1d-9f96-1fbb4568c75d'::uuid, 'personal-statement', 'Admission Essay', 'Submit an essay outlining reasons for choosing to become a nurse anesthetist, for choosing to attend a Christian faith-based institution, and for choosing AdventHealth University, specifically.', '[{"id": "q1", "text": "reasons for becoming a nurse anesthetist", "optional": false}, {"id": "q2", "text": "reasons for choosing a Christian faith-based institution", "optional": false}, {"id": "q3", "text": "reasons for choosing AdventHealth University specifically", "optional": false}]'::jsonb, null, null, null, null, null, null, null, null, null, null, null, null, null, null, '[]'::jsonb, null, false, '[]'::jsonb, true, 0, null, null, null, null, null, null, null, null),
