  ('79a3ae86-2111-5223-b64a-ee4084d90d38'::uuid, 'f68f751e-a5dc-56f2-8fb4-a8590fe4d8a5'::uuid, 'cd007953-bf0b-40bc-a8e0-8a71b0a79ed8'::uuid, 'other', 'Statement 3 — Doctor of Nursing Essay', 'Share your Doctor of Nursing Essay', '[]'::jsonb, null, 500, null, null, null, null, null, null, null, null, null, null, null, null, '[]'::jsonb, null, false, '[]'::jsonb, true, 2, 'target', 'length used adjectivally: "500-word statement"', null, null, null, null, null, null),
  ('10a0e18f-ae4b-5803-a718-788dea53404d'::uuid, '4ab785bd-8e57-5a43-9798-adf1f5ecc85b'::uuid, 'cf712a94-b479-4f27-a2e5-304a14ebea16'::uuid, 'goal-statement', 'Professional Goal Statement', 'Professional Goal Statement consisting of 500-1,000 words with attention given to the applicant''s professional goals, past experiences and contributions the applicant expects to make in the field Nurse Anesthesia practice.', '[{"id": "q1", "text": "professional goals", "optional": false}, {"id": "q2", "text": "past experiences", "optional": false}, {"id": "q3", "text": "contributions the applicant expects to make in nurse anesthesia practice — three topics WITHIN one statement", "optional": false}]'::jsonb, null, null, null, null, null, null, null, null, null, null, null, null, null, null, '[]'::jsonb, null, false, '[]'::jsonb, true, 0, null, null, null, null, null, null, 'Professional Goal Statement consisting of 500-1,000 words', true),
  ('d3d09d1a-208b-50d8-93ed-38ccd0f97416'::uuid, '80cea664-ae13-544f-b49b-9ef6f23415e7'::uuid, '9e39aa62-0928-4875-8977-09afdd60756b'::uuid, 'goal-statement', 'Goal Statement', 'The goal statement is your opportunity to tell us (as specifically as you can at this time) about your career plans after you finish your anesthesia program. Your goal statement should also include your understanding of the role of the nurse anesthetist and your career in this role (including where you would like to work). This statement provides us with a sample of your writing ability and helps faculty determine your fit with Bellarmine''s program.', '[{"id": "q1", "text": "career plans after finishing the anesthesia program", "optional": false}, {"id": "q2", "text": "understanding of the nurse anesthetist role", "optional": false}, {"id": "q3", "text": "career in this role, including where you would like to work — three topics WITHIN one statement", "optional": false}]'::jsonb, null, null, null, null, null, null, null, null, null, null, null, null, null, null, '[]'::jsonb, null, false, '[]'::jsonb, true, 0, null, null, null, null, null, null, null, null),
  ('d4e79cfc-8aa1-5c27-882b-3a9febbf3172'::uuid, 'ce3d0c83-4a23-5261-8058-097968872dab'::uuid, '49b3adfc-31c2-40a3-b952-6467069b80d8'::uuid, 'goal-statement', 'Goal Statement Essay 1', 'Nursing is both the art and science of human caring. Please elaborate on your reasons for wanting to become a registered nurse, nurse practitioner, or nurse anesthetist. Please describe the specialty and/or patient population with which you wish to study and how educational preparation in this specialty will enable you to achieve your future goals and plans.', '[{"id": "q1", "text": "reasons for wanting to become a nurse anesthetist", "optional": false}, {"id": "q2", "text": "the specialty and/or patient population you wish to study", "optional": false}, {"id": "q3", "text": "how educational preparation in that specialty will enable your future goals and plans", "optional": false}]'::jsonb, null, null, null, null, null, null, 1.5, 'double', null, null, null, null, null, null, '["Not stated (typewritten)"]'::jsonb, null, false, '[]'::jsonb, true, 0, null, null, null, null, 'enforced', 'explicit bound: "maximum"', null, null),
  ('9d03d444-bdc1-57b4-9f54-aa7d91630e69'::uuid, 'ce3d0c83-4a23-5261-8058-097968872dab'::uuid, '49b3adfc-31c2-40a3-b952-6467069b80d8'::uuid, 'personal-statement', 'Goal Statement Essay 2', 'The Boston College William F. Connell School of Nursing is committed to developing the whole person and preparing lifelong learners who will use knowledge in service of others. Please tell us something about yourself that may not have been captured in other parts of the application that demonstrates your personal development as a whole person who is a lifelong learner in service to others.', '[]'::jsonb, null, null, null, null, null, null, 1.5, 'double', null, null, null, null, null, null, '["Not stated (typewritten)"]'::jsonb, null, false, '[]'::jsonb, true, 1, null, null, null, null, 'enforced', 'explicit bound: "maximum"', null, null),
