  ('940dfa8f-2ba7-5d66-88a0-ed215ad74bbd'::uuid, 'b7018ad2-cae8-5919-821b-63648ba6ccc8'::uuid, '8feed176-bf33-4158-be0f-20d0aaf42d58'::uuid, 'additional-response', 'Optional Statement', 'Optional Statement: Highly encouraged. Please consider how your experiences and attributes would allow you to contribute to the Georgetown University School of Nursing''s Mission as a student and future CRNA.', '[]'::jsonb, null, null, null, null, null, null, null, null, null, null, null, null, null, null, '[]'::jsonb, null, true, '[]'::jsonb, true, 1, null, null, null, null, null, null, null, null),
  ('4a06e99c-e525-5551-88f0-c43bd4e25dd5'::uuid, 'c2d7974f-8a23-5f98-8129-e750ac5d632c'::uuid, 'dc5a27ae-8d00-462f-8d31-41e1b271db06'::uuid, 'personal-statement', 'Statement of Interest', 'Submit a statement of interest detailing your desire to pursue a career in nurse anesthesia practice, your long-term career goals, and identify a current clinical practice problem impacting nurse anesthesia practice.', '[{"id": "q1", "text": "desire to pursue a career in nurse anesthesia practice", "optional": false}, {"id": "q2", "text": "long-term career goals", "optional": false}, {"id": "q3", "text": "a current clinical practice problem impacting nurse anesthesia practice — three topics WITHIN one statement", "optional": false}]'::jsonb, null, null, null, null, null, null, 2, 'double', null, null, null, null, null, null, '["Times New Roman, 12 point; margins not stated"]'::jsonb, null, false, '[]'::jsonb, true, 0, null, null, null, null, 'enforced', 'explicit bound: "maximum"', null, null),
  ('3113b4d6-e0fe-5d21-850c-3c162bca70af'::uuid, '33115e48-21f6-5844-8e67-2629bea79cdd'::uuid, '31d3b6a1-9cf1-411b-8d8f-c7ca87df445a'::uuid, 'personal-statement', 'Personal Statement', 'A personal statement describing career goals and interest in graduate study is required as part of the application.', '[{"id": "q1", "text": "career goals", "optional": false}, {"id": "q2", "text": "interest in graduate study", "optional": false}]'::jsonb, null, null, null, null, null, null, null, null, null, null, null, null, null, null, '[]'::jsonb, null, false, '[]'::jsonb, true, 0, null, null, null, null, null, null, null, null),
  ('639b5fc7-0889-5ab7-a7a4-a937a1a8358c'::uuid, '4533e949-0618-522c-9ae6-44764eae5e3e'::uuid, 'f11bbcb4-6a67-4de0-8325-0bed2d2d1618'::uuid, 'goal-statement', 'Personal Statement of Professional Goals', 'Provide a personal statement of professional goals in 350 to 500 words.', '[]'::jsonb, null, null, null, null, null, null, null, null, null, null, null, null, null, null, '[]'::jsonb, null, false, '[]'::jsonb, true, 0, null, null, null, null, null, null, 'Provide a personal statement of professional goals in 350 to 500 words.', true),
  ('82af2a6f-b690-58c9-9f6e-8c2ab5af79df'::uuid, 'dcd90900-8db5-5b7f-ba01-28ab9823cd2e'::uuid, '6b9f3678-565f-4213-9cd1-7e5003d4e3a1'::uuid, 'personal-statement', 'Personal Statement', 'Applicants will need to address each of the following areas: Purpose of pursuing the DNP-CRNA track program; Areas of interest/professional plans as a CRNA; Goals after you complete the DNP-CRNA track program; Personal/professional qualities that will contribute to you success in our program; Challenges and rewards that you anticipate in our program; Rational for selecting our program.', '[{"id": "q1", "text": "Purpose of pursuing the DNP-CRNA track program", "optional": false}, {"id": "q2", "text": "Areas of interest/professional plans as a CRNA", "optional": false}, {"id": "q3", "text": "Goals after you complete the DNP-CRNA track program", "optional": false}, {"id": "q4", "text": "Personal/professional qualities that will contribute to you success in our program", "optional": false}, {"id": "q5", "text": "Challenges and rewards that you anticipate in our program", "optional": false}, {"id": "q6", "text": "Rational for selecting our program", "optional": false}]'::jsonb, null, null, null, null, null, null, null, 'double', null, null, null, null, null, null, '["Not stated (typed)"]'::jsonb, null, false, '[]'::jsonb, true, 0, null, null, null, null, null, null, '<2 pages (stated as ''less than two pages in length''), for the whole document', false),
  ('b717e3fd-d116-5fb7-b74b-0355a33cb143'::uuid, '9c649b16-d703-5151-84e6-c2fe5a67f10b'::uuid, '76e7a072-44eb-405f-a865-34e8f1dd4293'::uuid, 'personal-statement', 'Personal Statement / Essay', '1-2 pages in 12pt font on why you want to become a CRNA. Additional topics in your essay can include: your reasons for desiring to enter the field of nurse anesthesia; your professional experiences and activities since completion of your BSN; your professional accomplishments and awards; your plans and aspirations for the future; your participation in activities that promote FranU and DNP-NA values and mission.', '[]'::jsonb, null, null, null, null, null, null, null, null, null, null, null, null, null, null, '["12 pt font; family and margins not stated"]'::jsonb, null, false, '[]'::jsonb, true, 0, null, null, null, null, null, null, '1-2 pages in 12pt font on why you want to become a CRNA.', true),
  ('1f3ba87b-3c9f-5ec9-9b56-1d1b3ba60ee7'::uuid, '1c7bf14f-28eb-57a2-a22d-b69bb9b913e8'::uuid, 'fdc2eda3-6a52-4ae5-98ef-592def4c94f7'::uuid, 'personal-statement', 'Personal Statement', 'A written personal statement describing the candidate''s reasons for pursuing a doctoral degree in nurse anesthesia, professional goals in advanced practice nursing, and the experiences that have prepared them for success in full time doctoral education. The statement should utilize a business letter format and be no more than two pages in length.', '[{"id": "q1", "text": "reasons for pursuing a doctoral degree in nurse anesthesia", "optional": false}, {"id": "q2", "text": "professional goals in advanced practice nursing", "optional": false}, {"id": "q3", "text": "experiences that have prepared them for success in full-time doctoral education", "optional": false}]'::jsonb, null, null, null, null, null, null, 2, null, null, null, null, null, null, null, '["Business letter format (format instruction, not a citation style)"]'::jsonb, null, false, '[]'::jsonb, true, 0, null, null, null, null, 'enforced', 'explicit bound: "maximum"', null, null),
  ('bb79b81b-53d5-57b6-b890-d1b7c4c79cdc'::uuid, '081ab7bf-8473-531b-aa37-059dfc776bd8'::uuid, '23032d71-3b40-466f-8a20-1209730d9eda'::uuid, 'personal-statement', 'Professional Essay', 'A 2-3 page essay describing your interest in nurse anesthesia, shadow experiences (highly encouraged), thoughts on independent practice, and factors that will contribute to your success in the program.', '[{"id": "q1", "text": "interest in nurse anesthesia", "optional": false}, {"id": "q3", "text": "thoughts on independent practice", "optional": false}, {"id": "q4", "text": "factors that will contribute to your success in the program. HIGHLY ENCOURAGED rather than required: (2) shadow experiences", "optional": false}]'::jsonb, null, null, null, null, null, null, null, null, null, null, null, null, null, null, '[]'::jsonb, null, false, '[]'::jsonb, true, 0, null, null, null, null, null, null, 'A 2-3 page essay describing your interest in nurse anesthesia', true),
  ('e3e6a2b1-98d2-5ea1-ab36-0612418c8b10'::uuid, '01898b8b-1205-5d14-abec-ff735176c47e'::uuid, '12f44424-1446-4039-83d1-c05a145a679b'::uuid, 'goal-statement', 'Written Statement of Advanced Practice Goals', 'A written statement of advanced practice goals, including reason for interest in Johns Hopkins.', '[{"id": "q1", "text": "advanced practice goals", "optional": false}, {"id": "q2", "text": "reason for interest in Johns Hopkins", "optional": false}]'::jsonb, null, null, null, null, null, null, null, null, null, null, null, null, null, null, '[]'::jsonb, null, false, '[]'::jsonb, true, 0, null, null, null, null, null, null, null, null),
  ('2b0cfefa-7892-520c-bfd0-84633346f71c'::uuid, '2a6ce281-45e6-5b90-888a-0404c57d02c6'::uuid, '957b96cb-56d1-4454-a4bf-1aebcb32eace'::uuid, 'personal-statement', 'Personal Statement Letter', 'A personal statement letter (three pages, excluding cover and references in AMA format) addressing the following: A clear statement of your goals and expectations for entering the program; Your understanding of the role of a Certified Registered Nurse Anesthetist; include at least one article supporting your understanding, cited according to current AMA Format standards.', '[{"id": "q1", "text": "a clear statement of your goals and expectations for entering the program", "optional": false}, {"id": "q2", "text": "your understanding of the role of a CRNA", "optional": false}, {"id": "q3", "text": "at least one supporting article cited in AMA format", "optional": false}]'::jsonb, null, null, null, null, null, null, null, null, null, null, null, null, null, null, '["AMA format; at least one cited article required"]'::jsonb, null, false, '[]'::jsonb, true, 0, null, null, null, null, null, null, 'A personal statement letter (three pages, excluding cover and references in AMA format)', true),
  ('8a14bc2d-3ae8-5198-b837-24ae7ccaa963'::uuid, 'ae1901b5-0cc9-5f33-bab7-9a9f2f3862eb'::uuid, '79beb34e-7b73-4a8c-abbd-10283131a03d'::uuid, 'goal-statement', 'Career Goals Essay', 'A 500-word essay addressing your career goals.', '[]'::jsonb, null, 500, null, null, null, null, null, null, null, null, null, null, null, null, '[]'::jsonb, null, false, '[]'::jsonb, true, 0, 'enforced', 'explicit bound: "maximum"', null, null, null, null, null, null),
  ('ba27174a-1bce-57df-a2f2-72eac697887e'::uuid, '12a60b38-6ac6-5b39-b48b-22661c388be4'::uuid, 'f4d2fc17-62e1-4d7d-95e6-428edbd36472'::uuid, 'goal-statement', 'Statement of Interest', 'Please share why you want to be a CRNA, why you are choosing La Salle''s program, and where you see yourself in 5 years as it relates to your career goals.', '[{"id": "q1", "text": "why you want to be a CRNA", "optional": false}, {"id": "q2", "text": "why you are choosing La Salle''s program", "optional": false}, {"id": "q3", "text": "where you see yourself in 5 years as it relates to your career goals", "optional": false}]'::jsonb, null, null, null, null, null, 1, 2, 'double', null, null, null, null, null, null, '["Times New Roman 12; margins not stated"]'::jsonb, null, false, '[]'::jsonb, true, 0, null, null, null, null, 'enforced', 'explicit bound: "maximum"', null, null),
  ('c855e881-1613-51c8-9ba8-cb46baa47399'::uuid, '94f2dae4-4f12-54b1-aecb-68405a7c5f00'::uuid, 'dc9659c1-f0f7-48c9-a89e-c6671a1a76b3'::uuid, 'goal-statement', 'Personal Statement', 'Personal statement (no more than 500 words) about short-term and long-term goals after completion of the Doctor of Nursing Practice degree', '[{"id": "q1", "text": "short-term goals after completing the DNP", "optional": false}, {"id": "q2", "text": "long-term goals", "optional": false}]'::jsonb, null, 500, null, null, null, null, null, null, null, null, null, null, null, null, '[]'::jsonb, null, false, '[]'::jsonb, true, 0, 'enforced', 'explicit bound: "no more than"', null, null, null, null, null, null),
  ('1076d245-2328-53ee-b5c9-d5d62d01a2e1'::uuid, 'e54eecb8-a62d-51a3-9f4e-4d865989fba8'::uuid, '96e0c0db-f09e-4ced-af68-08210b099cdf'::uuid, 'goal-statement', 'Written Essay', 'Written essay outlining career goals and motivation.', '[{"id": "q1", "text": "career goals", "optional": false}, {"id": "q2", "text": "motivation", "optional": false}]'::jsonb, null, null, null, null, null, null, null, null, null, null, null, null, null, null, '[]'::jsonb, null, false, '[]'::jsonb, true, 0, null, null, null, null, null, null, null, null),
  ('99672993-8d65-5b9c-832a-fe61f16174ba'::uuid, '5d16cc78-cfda-5c1c-9f8d-8266b6d4d1bb'::uuid, '8ba46105-e505-416a-9b92-677a38d9e26c'::uuid, 'personal-statement', 'Personal Letter to the Admissions Committee', 'This letter should briefly describe your educational background, nursing experience, reason for desire to become a nurse anesthetist, and reason for desiring admission to MTSA, specifically.', '[{"id": "q1", "text": "educational background", "optional": false}, {"id": "q2", "text": "nursing experience", "optional": false}, {"id": "q3", "text": "reason for desire to become a nurse anesthetist", "optional": false}, {"id": "q4", "text": "reason for desiring admission to MTSA specifically", "optional": false}]'::jsonb, null, null, null, null, null, null, 1, 'single', null, null, null, null, null, null, '["12-point; family and margins not stated"]'::jsonb, null, false, '[]'::jsonb, true, 0, null, null, null, null, 'enforced', 'explicit bound: "maximum"', null, null),
  ('18a8d96e-8b14-5c14-ae70-b279e3d2761d'::uuid, 'c22f1052-0b29-5d23-84b5-74615b2f9234'::uuid, '859cc48d-162d-4d9f-99d7-69662242072a'::uuid, 'personal-statement', 'Admissions Essay', 'NMSU''s Nurse Anesthesiology Program is dedicated to improving healthcare access in rural and underserved communities and addressing healthcare disparities. Describe your motivation for becoming a nurse anesthesia provider and how your personal and professional goals align with our program''s mission to address health care disparities in rural communities. How do you envision using your skills to improve anesthesia care accessibility and outcomes in underserved populations?', '[{"id": "q1", "text": "motivation for becoming a nurse anesthesia provider and how personal/professional goals align with the program''s rural health-disparities mission", "optional": false}, {"id": "q2", "text": "how you envision using your skills to improve anesthesia care accessibility and outcomes in underserved populations", "optional": false}]'::jsonb, null, null, null, null, null, null, null, null, null, null, null, null, null, null, '["APA formatting"]'::jsonb, null, false, '[]'::jsonb, true, 0, null, null, null, null, null, null, 'Submit a 1-2 page essay using APA formatting.', true),
  ('4ebe0d1e-2918-5280-9d27-244f0fa52c1f'::uuid, 'e4839445-65a2-53c2-b2c5-c124b17419af'::uuid, 'ceb250a1-d02d-4d17-9a29-b8aa3400234c'::uuid, 'personal-statement', 'Personal Essay', 'A personal essay should be submitted in which the applicant demonstrates graduate-level writing ability. The personal essay should reflect the applicant''s professional development as a registered nurse in critical care and how this will translate to success in an advanced practice role as a nurse anesthetist. The personal statement should be 2 pages or less.', '[{"id": "q1", "text": "professional development as a registered nurse in critical care", "optional": false}, {"id": "q2", "text": "how that will translate to success in an advanced practice role as a nurse anesthetist. Explicit additional criterion: demonstrate graduate-level writing ability.", "optional": false}]'::jsonb, null, null, null, null, null, null, 2, null, null, null, null, null, null, null, '[]'::jsonb, null, false, '[]'::jsonb, true, 0, null, null, null, null, 'enforced', 'explicit bound: "or less"', null, null),
  ('a614a9ef-f08c-5252-9072-db6ab78eb576'::uuid, '524b63fc-69fc-5d0c-845b-12d8629f00d5'::uuid, 'ebd02a4c-1947-4e04-9c54-df2b82e74488'::uuid, 'goal-statement', 'Personal Goal Statement', 'Maximum two pages, addressing (1) Reason for pursuing a career as a CRNA, (2) Insights gained from CRNA shadowing, (3) Rationale for selecting the Northeastern DNP-NA program, and (4) Understanding of a scholarly project. This is an opportunity to highlight your experiences, passion, and vision as a future CRNA, and to demonstrate how you feel you will contribute to the program and the profession.', '[{"id": "q1", "text": "reason for pursuing a career as a CRNA", "optional": false}, {"id": "q2", "text": "insights gained from CRNA shadowing", "optional": false}, {"id": "q3", "text": "rationale for selecting the Northeastern DNP-NA program", "optional": false}, {"id": "q4", "text": "understanding of a scholarly project — four topics WITHIN one statement", "optional": false}]'::jsonb, null, null, null, null, null, null, 2, null, null, null, null, null, null, null, '[]'::jsonb, null, false, '[]'::jsonb, true, 0, null, null, null, null, 'enforced', 'explicit bound: "maximum"', null, null),
  ('ed3424a9-d410-54f9-b0a1-c929b07e75bd'::uuid, '7a54c014-84bf-5060-b3e0-bf9b26d91663'::uuid, 'ae40f2ac-b36b-433a-925a-855fd8047b56'::uuid, 'goal-statement', 'Goal Statement Essay', 'A 500-700 word essay that should speak specifically to the concentration area to which you are applying.', '[]'::jsonb, 500, 700, null, null, null, null, null, null, null, null, null, null, null, null, '[]'::jsonb, null, false, '[]'::jsonb, true, 0, 'target', 'length used adjectivally: "700 word essay"', null, null, null, null, null, null),
  ('dfd0cd87-ae77-5b75-8f94-986e60151ee8'::uuid, '2d07e630-1e2a-521a-8334-2d1fd6b56f97'::uuid, '6f539bc5-cd6c-4708-8bc0-b14062ca0aeb'::uuid, 'writing-sample', 'Written Essay — Patient Care and Safety Issue', 'Identify and describe a selected issue related to patient care and safety. Synthesize the research evidence related to the contemporary issue related to patient care and safety. Based on the research evidence, describe practice change(s) that should be considered. Summarize the impact the proposed practice change(s) would have on key stakeholders concerned with the selected contemporary issue related to patient care and safety. Maximum 2 pages, double spaced. A third page can be included for references.', '[{"id": "q1", "text": "identify and describe a selected patient care and safety issue", "optional": false}, {"id": "q2", "text": "synthesize the research evidence on it", "optional": false}, {"id": "q3", "text": "describe practice change(s) that should be considered, based on that evidence", "optional": false}, {"id": "q4", "text": "summarize the impact of the proposed change(s) on key stakeholders", "optional": false}]'::jsonb, null, null, null, null, null, null, null, 'double', null, null, null, null, null, null, '["Research evidence must be synthesized and referenced; no named style is specified"]'::jsonb, null, false, '[]'::jsonb, true, 0, null, null, null, null, null, null, '2 pages maximum, plus an optional 3rd page for references only', false),
  ('041bcb8d-4207-584a-b860-b6168e696509'::uuid, '02c09cfd-2151-58fb-9b46-3ea9632808bf'::uuid, 'e24bcd9c-9905-4bdc-ab66-977f265a5933'::uuid, 'goal-statement', 'Statement of Intent', 'The statement should be representative of the applicant''s writing ability. The statement should be two-to-four typed pages, double-spaced and written in 12-point font. [Purpose per the official page: demonstrate the candidate''s leadership and practice experience and reasons for pursuing doctoral study.]', '[{"id": "q1", "text": "leadership", "optional": false}, {"id": "q2", "text": "practice experience", "optional": false}, {"id": "q3", "text": "reasons for pursuing doctoral study. Explicit additional criterion: the statement is assessed as representative of the applicant''s writing ability.", "optional": false}]'::jsonb, null, null, null, null, null, 2, 4, 'double', null, null, null, null, null, null, '["12-point; family and margins not stated"]'::jsonb, null, false, '[]'::jsonb, true, 0, null, null, null, null, 'enforced', 'explicit bound: "maximum"', null, null),
  ('95e62249-5e97-5415-b2cb-2571a2a1a709'::uuid, '6932385e-0822-52ad-b774-e450188c6b4c'::uuid, '26b3b5f3-41fc-4529-aacf-4ea7f4aad218'::uuid, 'personal-statement', 'Career Motivation Essay', 'Applicants are required to submit a short essay explaining why they want to become a Certified Registered Nurse Anesthetist (CRNA).', '[]'::jsonb, null, null, null, null, null, null, null, null, null, null, null, null, null, null, '[]'::jsonb, null, false, '[]'::jsonb, true, 0, null, null, null, null, null, null, null, null),
  ('c8eb6be1-4704-570c-8af6-a8e7d45690c6'::uuid, 'e79a17f1-6440-55c7-9193-72fe3a9f58b7'::uuid, '076c4322-9b9d-4e31-8ffb-03b0d328b442'::uuid, 'goal-statement', 'Personal Statement', 'Submission of a personal statement describing the applicant''s personal career goals and interest in graduate study.', '[{"id": "q1", "text": "personal career goals", "optional": false}, {"id": "q2", "text": "interest in graduate study", "optional": false}]'::jsonb, null, null, null, null, null, null, null, null, null, null, null, null, null, null, '[]'::jsonb, null, false, '[]'::jsonb, true, 0, null, null, null, null, null, null, null, null),
  ('24dd131c-da14-5735-a1d9-278f7348897f'::uuid, '7e5aa590-8df0-518d-bcfd-b98cfa7f21bc'::uuid, '2473f4d9-844c-443e-85ee-a7834a49abb4'::uuid, 'personal-statement', 'Personal Statement', 'A Personal Statement, limited to one page*, describing a significant challenge you have faced in your academic or professional journey. How did you approach it, and what did you learn from the experience?', '[{"id": "q1", "text": "a significant challenge faced in your academic or professional journey", "optional": false}, {"id": "q2", "text": "how you approached it", "optional": false}, {"id": "q3", "text": "what you learned from the experience", "optional": false}]'::jsonb, null, null, null, null, null, null, 1, null, null, null, null, null, null, null, '[]'::jsonb, null, false, '[]'::jsonb, true, 0, null, null, null, null, 'enforced', 'explicit bound: "maximum"', null, null),
  ('01591a65-0626-55c4-993a-36143c825f9b'::uuid, '7e5aa590-8df0-518d-bcfd-b98cfa7f21bc'::uuid, '2473f4d9-844c-443e-85ee-a7834a49abb4'::uuid, 'writing-sample', 'Writing Sample', 'A writing sample, limited to one page*, reflecting on an unusual skill or a distinctive background, and explain how it influences your work, interactions, or goals.', '[{"id": "q1", "text": "an unusual skill or distinctive background", "optional": false}, {"id": "q2", "text": "how it influences your work, interactions, or goals", "optional": false}]'::jsonb, null, null, null, null, null, null, 1, null, null, null, null, null, null, null, '[]'::jsonb, null, false, '[]'::jsonb, true, 1, null, null, null, null, 'enforced', 'explicit bound: "maximum"', null, null),
  ('4f4c6bc4-e491-5f8a-a635-73fbd4d1567f'::uuid, '0eb7cbe5-9a3f-5370-bb77-aae7bea52ef9'::uuid, 'fef27c4e-a9a8-4dd4-82d9-92c8c218ff8f'::uuid, 'personal-statement', 'Personal Statement (blinded)', 'Include: a brief description of the applicant''s background, training, and experience; a statement indicating the career goals of the applicant and their reasons for seeking admission to the program; a description of the areas the applicant considers to be their strengths and areas in which the applicant wishes to develop greater strengths and abilities; and personal information the applicant wishes to share. Please do not state any personal identifying information within the essay, as the essays are blinded for the readers to ensure a fair process.', '[{"id": "q1", "text": "background, training and experience", "optional": false}, {"id": "q2", "text": "career goals and reasons for seeking admission", "optional": false}, {"id": "q3", "text": "strengths and areas in which the applicant wishes to develop greater strengths and abilities", "optional": false}, {"id": "q4", "text": "personal information the applicant wishes to share", "optional": false}]'::jsonb, null, null, null, null, null, null, null, null, null, null, null, null, null, null, '["BLINDED REVIEW — no personal identifying information may appear in the essay"]'::jsonb, null, false, '[]'::jsonb, true, 0, null, null, null, null, null, null, null, null),
  ('6ea7a272-d705-56f2-9745-dbfdff27fec8'::uuid, '14c18c10-c00e-50d7-862a-e112de7b8f52'::uuid, '1c5e46d1-d436-465c-9d31-c6dcaf029056'::uuid, 'personal-statement', 'Personal Statement', 'Personal statement (600 words max) describing the applicant''s rationale in their pursuit of a practice doctorate in nurse anesthesia and possible future roles as a CRNA.', '[{"id": "q1", "text": "rationale for pursuing a practice doctorate in nurse anesthesia", "optional": false}, {"id": "q2", "text": "possible future roles as a CRNA", "optional": false}]'::jsonb, null, 600, null, null, null, null, null, null, null, null, null, null, null, null, '[]'::jsonb, null, false, '[]'::jsonb, true, 0, 'enforced', 'explicit bound: "max"', null, null, null, null, null, null),
  ('da367d6c-9a8f-5407-96db-46ac901f7fe6'::uuid, '544aa482-d88f-597e-99f3-667728756753'::uuid, 'b50d5e09-9870-4708-916b-e8b5e4aa44dc'::uuid, 'goal-statement', 'Professional Education Statement', 'Professional Education Statement that includes: Your reasons for applying to the CRNA program. Your long- and short-term educational and professional goals and how the CRNA program will help you reach those goals. How your degree will enhance your experience. How you plan to accommodate the program''s rigorous curriculum with all of your competing activities and doctoral study. The population you would like to focus on for your CRNA project and describe one clinical problem related to the population that your project will help address. How, as a doctorally prepared advanced practice nurse, you will contribute (e.g., through education, research, and practice) to enhance the health and quality of life for people of all cultures, economic levels, and geographic locations.', '[{"id": "q1", "text": "reasons for applying to the CRNA program", "optional": false}, {"id": "q2", "text": "long- and short-term educational and professional goals and how the program will help reach them", "optional": false}, {"id": "q3", "text": "how your degree will enhance your experience", "optional": false}, {"id": "q4", "text": "how you plan to accommodate the rigorous curriculum with competing activities and doctoral study", "optional": false}, {"id": "q5", "text": "the population for your CRNA project and one clinical problem it will help address", "optional": false}, {"id": "q6", "text": "how you will contribute, through education, research and practice, to enhance health and quality of life for people of all cultures, economic levels and geographic locations", "optional": false}]'::jsonb, null, null, null, null, null, null, null, null, null, null, null, null, null, null, '[]'::jsonb, null, false, '[]'::jsonb, true, 0, null, null, null, null, null, null, null, null),
  ('c1c80521-f07c-50e0-864c-08e7ca2c3a62'::uuid, '6d7fa319-b706-50ea-9f34-309ad39b802e'::uuid, '934fc115-0094-4217-ab42-7e8a45c3da62'::uuid, 'goal-statement', 'DNP Vision Statement', 'The DNP Vision Statement is a 250 - 500 word description of the applicant''s future intentions and goals upon completion of a particular BSN-DNP track as a DNP graduate. The Statement should clearly express the applicant''s reasons for applying to the SLUHN/DSU Nurse Anesthesia Track and future professional and leadership goals as a doctorally-prepared Advanced Practice Registered Nurse.', '[{"id": "q1", "text": "future intentions and goals upon completing the BSN-DNP track as a DNP graduate", "optional": false}, {"id": "q2", "text": "reasons for applying to the SLUHN/DSU Nurse Anesthesia Track", "optional": false}, {"id": "q3", "text": "future professional and leadership goals as a doctorally-prepared APRN", "optional": false}]'::jsonb, null, null, null, null, null, null, null, null, null, null, null, null, null, null, '[]'::jsonb, null, false, '[]'::jsonb, true, 0, null, null, null, null, null, null, 'The DNP Vision Statement is a 250 - 500 word description of the applicant''s future intentions and goals upon completion of a particular BSN-DNP track as a DNP graduate.', true),
  ('afb0a6fb-9de8-52b0-be6a-8c51f8369834'::uuid, '235262da-d2f0-5980-989e-822d384fb3b6'::uuid, '1e61b32e-402b-4dfe-a139-39d020311838'::uuid, 'goal-statement', 'Purpose and Goals Statement', 'Upload a statement describing your professional experience, career goals and alignment with the goals of the DNP Nurse Anesthesia program. Keep your statement no longer than three single-spaced pages. The statement should demonstrate your writing skills and show alignment between your goals and those of the program. Address the following: Include rationale for selecting the Nurse Anesthesia DNP program and how completing the program will assist you in achieving your professional and educational goals. What specifically are your academic and career goals for which the DNP program will prepare you best? How have your life experiences prepared you for being a doctoral-prepared nurse? Why are you seeking education in the DNP program at this time in your career?', '[{"id": "q1", "text": "rationale for selecting the Nurse Anesthesia DNP program and how completing it will assist in achieving professional and educational goals", "optional": false}, {"id": "q2", "text": "what specifically are your academic and career goals for which the DNP program will prepare you best", "optional": false}, {"id": "q3", "text": "how have your life experiences prepared you for being a doctoral-prepared nurse", "optional": false}, {"id": "q4", "text": "why are you seeking education in the DNP program at this time in your career. Plus the overarching topics: professional experience, career goals, and alignment with the program''s goals.", "optional": false}]'::jsonb, null, null, null, null, null, null, 3, 'single', null, null, null, null, null, null, '[]'::jsonb, null, false, '[]'::jsonb, true, 0, null, null, null, null, 'enforced', 'explicit bound: "maximum"', null, null),
  ('5d04ab9e-571e-59c8-8cd7-a41488bfbaf2'::uuid, '57e220b7-352e-5fb2-9c60-a13dfeeb815e'::uuid, '63c7be34-4f21-409c-a0a8-94372e4e60b6'::uuid, 'goal-statement', 'Position Paper', '300 word position paper describing professional goals and specific desire to seek graduate education at The University of Akron.', '[{"id": "q1", "text": "professional goals", "optional": false}, {"id": "q2", "text": "specific desire to seek graduate education at The University of Akron", "optional": false}]'::jsonb, null, 300, null, null, null, null, null, null, null, null, null, null, null, null, '[]'::jsonb, null, false, '[]'::jsonb, true, 0, 'target', 'length used adjectivally: "300 word position paper"', null, null, null, null, null, null),
  ('cafc159b-6981-5128-8350-6e5b8d7271c7'::uuid, '1624c0fb-552f-5538-b6dd-35f35e961f1d'::uuid, '02ce9071-5dc6-4aa8-998e-36a02b39fa96'::uuid, 'goal-statement', 'Goal Statement', 'Purpose: Describe why you are seeking a Doctor of Nursing Practice (DNP) degree at this point in your career. Future Contributions: What are your long-term professional goals as a DNP-prepared nurse? Selected Population: Identify the population you plan to focus on during your doctoral studies. Dual Program Applicants Only: If you are applying for a dual program, please describe your reasons for pursuing dual preparation. Please limit each response to 250 words. [Statement] no more than 2 pages in length.', '[{"id": "q1", "text": "Purpose — why you are seeking a DNP at this point in your career", "optional": false}, {"id": "q2", "text": "Future Contributions — long-term professional goals as a DNP-prepared nurse", "optional": false}, {"id": "q3", "text": "Selected Population — the population you plan to focus on during doctoral studies. CONDITIONAL, dual-program applicants only: (4) reasons for pursuing dual preparation.", "optional": false}]'::jsonb, null, 250, null, null, null, null, 2, null, null, null, null, null, null, null, '[]'::jsonb, null, false, '[]'::jsonb, true, 0, 'enforced', 'explicit bound: "no more than"', null, null, 'enforced', 'explicit bound: "maximum"', null, null),
  ('cd158851-59b7-5c4d-befc-5e3acc9f79cf'::uuid, '665231d6-e086-5050-b641-333dd24287bc'::uuid, 'af651687-1b4f-4382-9270-e059a7e4ab9e'::uuid, 'personal-statement', 'Personal Statement', 'Personal statement explaining your interests, motivations, and goals in pursuing a career as a CRNA', '[{"id": "q1", "text": "interests", "optional": false}, {"id": "q2", "text": "motivations", "optional": false}, {"id": "q3", "text": "goals in pursuing a career as a CRNA", "optional": false}]'::jsonb, null, null, null, null, null, null, null, null, null, null, null, null, null, null, '[]'::jsonb, null, false, '[]'::jsonb, true, 0, null, null, null, null, null, null, null, null),
  ('3908d30b-ab9a-597e-993e-b97b5dfbf62f'::uuid, 'cb55cf7d-83ed-5c2f-830f-c159585a06a6'::uuid, '68095d7d-639d-4a81-a218-211eab7733de'::uuid, 'personal-statement', 'DNP Admission Essay', 'The purpose of this three to five double-spaced page essay (MINIMUM 5000 characters - not counting spaces and MAXIMUM 18,000 characters - not counting spaces) is to provide the Admission Committee insight into your professional goals and expectations and to evaluate your written communication skills. Please address the following prompts: (1) There are two terminal degrees in the nursing profession. Explain the difference between the PhD and DNP-prepared nurse, and discuss why you chose the DNP degree? (1-2 pages) (2) The College of Nursing is dedicated to removing barriers to educational opportunities. Our collective strengths make us stronger, and we are committed to promoting an atmosphere where all members of the University community feel welcome, can thrive, and achieve success. Please tell us how you believe you will contribute to this community within the College of Nursing and how this will translate into your future contributions into the nursing community. (1-2 pages).', '[{"id": "q1", "text": "explain the difference between the PhD and DNP-prepared nurse and why you chose the DNP (1-2 pages)", "optional": false}, {"id": "q2", "text": "how you will contribute to the College of Nursing community and how that will translate into future contributions to the nursing community (1-2 pages)", "optional": false}]'::jsonb, null, null, 5000, 18000, false, 3, 5, 'double', null, null, null, null, null, null, '[]'::jsonb, null, false, '[]'::jsonb, true, 0, null, null, 'enforced', 'explicit bound: "maximum"', 'enforced', 'explicit bound: "maximum"', null, null),
  ('673ed33c-039b-5298-a563-4e4538bffbaa'::uuid, 'a2b120de-5b0b-54bb-a0d2-1095ce84f00c'::uuid, '9971c4d4-81a1-4738-95fe-e3618f37c753'::uuid, 'personal-statement', 'Personal Statement', 'A personal statement of 400 words or less that discusses the applicant''s nursing background and discusses future goals.', '[{"id": "q1", "text": "the applicant''s nursing background", "optional": false}, {"id": "q2", "text": "future goals", "optional": false}]'::jsonb, null, 400, null, null, null, null, null, null, null, null, null, null, null, null, '[]'::jsonb, null, false, '[]'::jsonb, true, 0, 'enforced', 'explicit bound: "or less"', null, null, null, null, null, null),
  ('a76e0da3-c8f7-544a-85de-c81125906659'::uuid, '2f3ddc30-b90e-5eac-b1c3-629d896b4977'::uuid, 'f830ba77-425e-4f70-b4cb-7602f9f24970'::uuid, 'personal-statement', 'Personal Statement', 'No more than 1,000 words, double-spaced and typewritten, free of grammatical/mechanical errors, including your name and the program you are applying for. (1) Articulate your reasons (including career goals) for gaining an advance practice degree. (2) Describe at least two qualities you possess that make you a good formal or informal leader, with examples. (3) Discuss an experience in collaborative teamwork using examples from any aspect of your life. (4) Provide an example of how you have worked with diverse populations locally, nationally or globally, and explain how graduate education will develop these skills. (5) Optional additional comments: please provide any additional comments that you feel the committee should be aware of. Citations are not required.', '[{"id": "q1", "text": "reasons, including career goals, for gaining an advanced practice degree", "optional": false}, {"id": "q2", "text": "at least two leadership qualities with examples", "optional": false}, {"id": "q3", "text": "an experience in collaborative teamwork with examples", "optional": false}, {"id": "q4", "text": "an example of working with diverse populations locally, nationally or globally and how graduate education will develop those skills. OPTIONAL: (5) any additional comments the committee should be aware of.", "optional": false}]'::jsonb, null, 1000, null, null, null, null, null, 'double', null, null, null, null, null, null, '["Typewritten; font and margins not stated", "Citations NOT required"]'::jsonb, null, false, '[]'::jsonb, true, 0, 'enforced', 'explicit bound: "no more than"', null, null, null, null, null, null),
  ('bb6fb9f2-d079-5f58-b083-4894b323c660'::uuid, 'abbff745-ac83-5ce3-8b0d-96d7839f2890'::uuid, 'a317f5e8-2723-4f28-8bed-db4bda42a88b'::uuid, 'goal-statement', 'Personal Goals Statement', 'The purpose of this statement is to provide the nurse anesthesia faculty further insight into the professional goals, motivation, and expectations of the applicant and to evaluate written communication skills. This statement is to be submitted with the application. Please keep statements to 250 words or less.', '[]'::jsonb, null, 250, null, null, null, null, null, null, null, null, null, null, null, null, '[]'::jsonb, null, false, '[]'::jsonb, true, 0, 'enforced', 'explicit bound: "or less"', null, null, null, null, null, null),
  ('e3ba199a-b767-5a60-a612-9f4152512625'::uuid, 'abbff745-ac83-5ce3-8b0d-96d7839f2890'::uuid, 'a317f5e8-2723-4f28-8bed-db4bda42a88b'::uuid, 'other', 'On-campus Interview Essay', 'The purpose of the essay is to provide the nurse anesthesia faculty further insight into the professional goals, motivation, and expectations of the applicant and to evaluate written communication skills. Applicants are asked to provide written responses to specific questions during their on-campus interview session.', '[]'::jsonb, null, null, null, null, null, null, null, null, null, null, null, null, null, null, '[]'::jsonb, null, false, '[]'::jsonb, true, 1, null, null, null, null, null, null, null, null),
  ('c6466a7b-7d2b-5ec8-9970-de2bd772c020'::uuid, '65ec5791-fcfe-52c6-87b4-48f575bb680e'::uuid, 'd1877515-b72e-455b-ba0e-e03a8dd999d6'::uuid, 'personal-statement', 'Professional Autobiography', 'A professional autobiography in essay form delineating personal goals of graduate study. Briefly describe your critical care nursing experience during the past five years. Mention briefly your roles and responsibilities, what types of patients you care for, and the size and location of your ICU. How do you perceive the role of the nurse anesthetist? Why did you select nurse anesthesiology as a career choice? Why did you select the University of Detroit Mercy program? What do you feel you have to offer the profession of nurse anesthesiology?', '[{"id": "q1", "text": "critical care nursing experience over the past five years, including roles and responsibilities, types of patients, and the size and location of your ICU", "optional": false}, {"id": "q2", "text": "how you perceive the role of the nurse anesthetist", "optional": false}, {"id": "q3", "text": "why you selected nurse anesthesiology as a career choice", "optional": false}, {"id": "q4", "text": "why you selected the University of Detroit Mercy program", "optional": false}, {"id": "q5", "text": "what you feel you have to offer the profession of nurse anesthesiology", "optional": false}]'::jsonb, null, null, null, null, null, null, 2, 'single', null, null, null, null, null, null, '["12-point Times New Roman, 1 inch margins"]'::jsonb, null, false, '[]'::jsonb, true, 0, null, null, null, null, 'enforced', 'explicit bound: "maximum"', null, null),
  ('e2c8899b-52e7-5aac-bf14-2b3074383e2d'::uuid, '031c35c4-5a64-57a4-ab92-910c7b135faa'::uuid, 'fcb0020c-1c6e-4338-b765-f822eca3103a'::uuid, 'additional-response', 'Essay 1 — Experiences Leading to the Specialty', 'Describe your personal or professional experiences(s) in health care and how these experiences led you to choose the specialty that you are applying to.', '[{"id": "q1", "text": "personal or professional experiences in health care", "optional": false}, {"id": "q2", "text": "how they led you to choose this specialty", "optional": false}]'::jsonb, null, null, null, null, null, null, null, null, null, null, null, null, null, null, '[]'::jsonb, null, false, '[]'::jsonb, true, 0, null, null, null, null, null, null, null, null),
  ('0c7c760b-74f0-53bf-9d2f-469070d1186b'::uuid, '031c35c4-5a64-57a4-ab92-910c7b135faa'::uuid, 'fcb0020c-1c6e-4338-b765-f822eca3103a'::uuid, 'additional-response', 'Essay 2 — When Doing the Right Thing Was Difficult', 'Describe a situation from your clinical, academic or professional experiences when doing the right thing was difficult. What did you do and what guided your decision?', '[{"id": "q1", "text": "the situation", "optional": false}, {"id": "q2", "text": "what you did", "optional": false}, {"id": "q3", "text": "what guided your decision", "optional": false}]'::jsonb, null, null, null, null, null, null, null, null, null, null, null, null, null, null, '[]'::jsonb, null, false, '[]'::jsonb, true, 1, null, null, null, null, null, null, null, null),
  ('caca81e1-ac0c-5142-9f0e-90d8c2383c30'::uuid, '031c35c4-5a64-57a4-ab92-910c7b135faa'::uuid, 'fcb0020c-1c6e-4338-b765-f822eca3103a'::uuid, 'additional-response', 'Essay 3 — Receiving Critical Feedback', 'Describe a time when you received critical feedback. How did you respond to it and what did you learn about yourself?', '[{"id": "q1", "text": "a time you received critical feedback", "optional": false}, {"id": "q2", "text": "how you responded", "optional": false}, {"id": "q3", "text": "what you learned about yourself", "optional": false}]'::jsonb, null, null, null, null, null, null, null, null, null, null, null, null, null, null, '[]'::jsonb, null, false, '[]'::jsonb, true, 2, null, null, null, null, null, null, null, null),
  ('9184d807-6920-550e-9a4d-6230119397dd'::uuid, '031c35c4-5a64-57a4-ab92-910c7b135faa'::uuid, 'fcb0020c-1c6e-4338-b765-f822eca3103a'::uuid, 'additional-response', 'Essay 4 — Why UIC', 'Why did you choose UIC to pursue a DNP degree? What part of the UIC Nursing mission statement resonates with you and why?', '[{"id": "q1", "text": "why UIC for a DNP", "optional": false}, {"id": "q2", "text": "which part of the UIC Nursing mission statement resonates with you and why", "optional": false}]'::jsonb, null, null, null, null, null, null, null, null, null, null, null, null, null, null, '[]'::jsonb, null, false, '[]'::jsonb, true, 3, null, null, null, null, null, null, null, null),
