  end if;
  if to_regclass('public.statement_requirements') is null then
    v_fail := array_append(v_fail, '005 signature: public.statement_requirements is missing');
  end if;
  if to_regclass('public.schools') is null then
    v_fail := array_append(v_fail, 'public.schools is missing, so no school_id can be validated');
  end if;

  -- 006 signature: the eight register columns
  select count(*) into v_n from information_schema.columns
   where table_schema = 'public' and table_name = 'statement_requirements'
     and column_name in ('words_enforcement','words_stated_as',
          'characters_enforcement','characters_stated_as','pages_enforcement',
          'pages_stated_as','unenforced_length','unenforced_length_verbatim');
  if v_n <> 8 then
    v_fail := array_append(v_fail, format('006 signature: %s of 8 register columns present', v_n));
  end if;

  -- 2 + 007 signature: all nine document types are accepted
  select pg_get_constraintdef(oid) into v_def from pg_constraint
   where conname = 'statement_requirements_document_type_known'
     and conrelid = 'public.statement_requirements'::regclass;
  if v_def is null then
    v_fail := array_append(v_fail, 'the document_type constraint is missing');
  else
    foreach v_t in array array['personal-statement', 'goal-statement', 'diversity-statement', 'writing-sample', 'additional-response', 'other', 'statement-of-purpose', 'autobiographical-essay', 'supplemental-essay'] loop
      if v_def not like '%' || quote_literal(v_t) || '%' then
        v_fail := array_append(v_fail, format('007 signature: document_type %s is not accepted', v_t));
      end if;
    end loop;
  end if;

  -- 3. page columns carry the post-007 type
  for v_t in select unnest(array['min_pages','max_pages']) loop
    if not exists (select 1 from information_schema.columns
                    where table_schema = 'public'
                      and table_name = 'statement_requirements'
                      and column_name = v_t and data_type = 'numeric'
                      and numeric_precision = 4 and numeric_scale = 1) then
      v_fail := array_append(v_fail, format('007 signature: %s is not numeric(4,1)', v_t));
    end if;
  end loop;

  -- 5 + 6. the catalog must be EMPTY. Not "mostly empty".
  select count(*) into v_n from public.statement_requirement_sets;
  if v_n <> 0 then
    v_fail := array_append(v_fail, format('statement_requirement_sets already holds %s row(s). This import is for an empty catalog; it does not merge. Run the postcheck and classify the state before any retry.', v_n));
  end if;
  select count(*) into v_n from public.statement_requirements;
  if v_n <> 0 then
    v_fail := array_append(v_fail, format('statement_requirements already holds %s row(s)', v_n));
  end if;

  -- 12. exact cardinality of the staged payload
  select count(*) into v_n from _import_sets;
  if v_n <> 63 then
    v_fail := array_append(v_fail, format('payload has %s sets, expected exactly 63', v_n));
  end if;
  select count(*) into v_n from _import_docs;
  if v_n <> 80 then
    v_fail := array_append(v_fail, format('payload has %s documents, expected exactly 80', v_n));
  end if;

  -- 7 + 8. every school_id exists, exactly once. No id is invented here:
  -- each one came from the owner-approved reconciliation.
  select count(*) into v_n from _import_sets s
   where not exists (select 1 from public.schools h where h.id = s.school_id);
  if v_n <> 0 then
    v_fail := array_append(v_fail, format('%s payload school_id(s) are absent from public.schools', v_n));
  end if;
  select count(*) into v_n from (
    select s.school_id from _import_sets s
      join public.schools h on h.id = s.school_id
     group by s.school_id having count(h.id) <> 1) q;
  if v_n <> 0 then
    v_fail := array_append(v_fail, format('%s payload school_id(s) do not resolve to exactly one school row', v_n));
  end if;
  select count(*) into v_n from (
    select school_id from _import_sets group by school_id having count(*) > 1) q;
  if v_n <> 0 then
    v_fail := array_append(v_fail, format('%s school_id(s) appear in more than one payload set', v_n));
  end if;

  -- 9. every source_url satisfies the constraint 005 will apply
  select count(*) into v_n from _import_sets
   where source_url is null or source_url !~ '^https?://[^[:space:]]+$';
  if v_n <> 0 then
    v_fail := array_append(v_fail, format('%s set(s) carry a source_url the schema would refuse', v_n));
  end if;
  select count(*) into v_n from _import_sets where verified_on is null;
  if v_n <> 0 then
    v_fail := array_append(v_fail, format('%s set(s) carry no verified_on', v_n));
  end if;

  -- 10. nothing is activated by this import
  select count(*) into v_n from _import_sets where is_active is not false;
  if v_n <> 0 then
    v_fail := array_append(v_fail, format('%s payload set(s) are not is_active = false', v_n));
  end if;

  -- 11. no held-back programme, by slug OR by school id
  select count(*) into v_n from _import_sets s
    join _held_back b on b.school_id = s.school_id;
  if v_n <> 0 then
    v_fail := array_append(v_fail, format('%s payload set(s) carry a HELD-BACK school id', v_n));
  end if;

  -- the verification statuses and document types the payload may contain
  select count(*) into v_n from _import_sets
   where verification_status not in ('unverified','needs-review','verified','conflicting');
  if v_n <> 0 then
    v_fail := array_append(v_fail, format('%s set(s) carry an unknown verification_status', v_n));
  end if;
  select count(*) into v_n from _import_docs
   where document_type not in ('personal-statement', 'goal-statement', 'diversity-statement', 'writing-sample', 'additional-response', 'other', 'statement-of-purpose', 'autobiographical-essay', 'supplemental-essay');
  if v_n <> 0 then
    v_fail := array_append(v_fail, format('%s document(s) carry an unsupported document_type', v_n));
  end if;

  -- the 006 length-register rules, checked on the PAYLOAD so a violation
  -- is reported as a refusal rather than as a raw constraint violation
  select count(*) into v_n from _import_docs
   where unenforced_length is not null
     and (min_words is not null or max_words is not null
       or min_characters is not null or max_characters is not null
       or min_pages is not null or max_pages is not null);
  if v_n <> 0 then
    v_fail := array_append(v_fail, format('%s staged document(s) carry unenforced_length beside a numeric bound, which 006 forbids', v_n));
  end if;
  select count(*) into v_n from _import_docs
   where unenforced_length_verbatim is not null and unenforced_length is null;
  if v_n <> 0 then
    v_fail := array_append(v_fail, format('%s staged document(s) carry the verbatim flag with no text', v_n));
  end if;
  select count(*) into v_n from _import_docs
   where coalesce(words_enforcement, 'enforced') not in ('truncated', 'enforced', 'target', 'suggested', 'unknown')
      or coalesce(characters_enforcement, 'enforced') not in ('truncated', 'enforced', 'target', 'suggested', 'unknown')
      or coalesce(pages_enforcement, 'enforced') not in ('truncated', 'enforced', 'target', 'suggested', 'unknown');
  if v_n <> 0 then
    v_fail := array_append(v_fail, format('%s staged document(s) carry an invalid enforcement category', v_n));
  end if;
  select count(*) into v_n from _import_docs
   where (words_enforcement = 'truncated' and max_words is null)
      or (characters_enforcement = 'truncated' and max_characters is null)
      or (pages_enforcement = 'truncated' and max_pages is null);
  if v_n <> 0 then
    v_fail := array_append(v_fail, format('%s staged truncated register(s) have no maximum', v_n));
  end if;

  -- every document belongs to a staged set
  select count(*) into v_n from _import_docs d
   where not exists (select 1 from _import_sets s where s.id = d.set_id);
  if v_n <> 0 then
    v_fail := array_append(v_fail, format('%s document(s) reference no staged set', v_n));
  end if;
  select count(*) into v_n from _import_docs d
    join _import_sets s on s.id = d.set_id
   where d.school_id <> s.school_id;
  if v_n <> 0 then
    v_fail := array_append(v_fail, format('%s document(s) disagree with their set about school_id', v_n));
  end if;

  if array_length(v_fail, 1) is not null then
    raise exception E'IMPORT REFUSED. % precondition(s) failed and NOTHING WAS INSERTED:
  - %',
      array_length(v_fail, 1), array_to_string(v_fail, E'
  - ');
  end if;
  raise notice 'preconditions passed: empty catalog, 63 sets / 80 documents staged, every school_id resolved, no held-back programme present';
end
$precond$;

-- ---- THE ONLY TWO STATEMENTS THAT WRITE ---------------------------------
insert into public.statement_requirement_sets (id, school_id, application_cycle, verification_status, source_url, verified_on, is_verbatim, original_text, notes, is_active, display_order)
select id, school_id, application_cycle, verification_status, source_url, verified_on, is_verbatim, original_text, notes, is_active, display_order from _import_sets;

insert into public.statement_requirements (id, set_id, school_id, document_type, label, prompt_text, components, min_words, max_words, min_characters, max_characters, characters_include_spaces, min_pages, max_pages, page_spacing, font_size_pt, font_family, margins_inches, citation_style, citation_family, min_references, other_instructions, choice_group, is_optional, notes, is_active, display_order, words_enforcement, words_stated_as, characters_enforcement, characters_stated_as, pages_enforcement, pages_stated_as, unenforced_length, unenforced_length_verbatim)
select id, set_id, school_id, document_type, label, prompt_text, components, min_words, max_words, min_characters, max_characters, characters_include_spaces, min_pages, max_pages, page_spacing, font_size_pt, font_family, margins_inches, citation_style, citation_family, min_references, other_instructions, choice_group, is_optional, notes, is_active, display_order, words_enforcement, words_stated_as, characters_enforcement, characters_stated_as, pages_enforcement, pages_stated_as, unenforced_length, unenforced_length_verbatim from _import_docs;

-- ---- POSTCONDITIONS, STILL INSIDE THE TRANSACTION ----------------------
-- Anything wrong here rolls the whole import back, so the catalog is never
-- left half-right.
do $postcond$
declare
  v_fail text[] := '{}';
  v_n    bigint;
begin
  select count(*) into v_n from public.statement_requirement_sets
   where id in (select id from _import_sets);
  if v_n <> 63 then v_fail := array_append(v_fail, format('%s of 63 sets landed', v_n)); end if;
  select count(*) into v_n from public.statement_requirement_sets;
  if v_n <> 63 then v_fail := array_append(v_fail, format('the table holds %s sets, expected exactly 63', v_n)); end if;

  select count(*) into v_n from public.statement_requirements
   where id in (select id from _import_docs);
  if v_n <> 80 then v_fail := array_append(v_fail, format('%s of 80 documents landed', v_n)); end if;
  select count(*) into v_n from public.statement_requirements;
  if v_n <> 80 then v_fail := array_append(v_fail, format('the table holds %s documents, expected exactly 80', v_n)); end if;

  select count(*) into v_n from public.statement_requirement_sets where is_active;
  if v_n <> 0 then v_fail := array_append(v_fail, format('%s imported set(s) are ACTIVE; this import activates nothing', v_n)); end if;

  select count(*) into v_n from public.statement_requirements d
   where not exists (select 1 from public.statement_requirement_sets s
                      where s.id = d.set_id);
  if v_n <> 0 then v_fail := array_append(v_fail, format('%s document(s) are orphaned', v_n)); end if;

  select count(*) into v_n from public.statement_requirements d
    join public.statement_requirement_sets s on s.id = d.set_id
   where d.school_id <> s.school_id;
  if v_n <> 0 then v_fail := array_append(v_fail, format('%s document(s) disagree with their set about school_id', v_n)); end if;

  select count(*) into v_n from (select school_id from public.statement_requirement_sets
    group by school_id having count(*) > 1) q;
  if v_n <> 0 then v_fail := array_append(v_fail, format('%s school(s) have more than one set', v_n)); end if;
  select count(*) into v_n from (select set_id, label from public.statement_requirements
    group by set_id, label having count(*) > 1) q;
  if v_n <> 0 then v_fail := array_append(v_fail, format('%s duplicate (set, label) document identit(ies)', v_n)); end if;

  select count(*) into v_n from public.statement_requirement_sets
   where school_id is null or verification_status is null or source_url is null
      or verified_on is null or original_text is null or notes is null;
  if v_n <> 0 then v_fail := array_append(v_fail, format('%s set(s) have a NULL required field', v_n)); end if;
  select count(*) into v_n from public.statement_requirements
   where set_id is null or school_id is null or document_type is null
      or btrim(coalesce(label,'')) = '' or btrim(coalesce(prompt_text,'')) = ''
      or components is null or other_instructions is null or notes is null;
  if v_n <> 0 then v_fail := array_append(v_fail, format('%s document(s) have a NULL or blank required field', v_n)); end if;

  select count(*) into v_n from public.statement_requirement_sets s
    join _held_back b on b.school_id = s.school_id;
  if v_n <> 0 then v_fail := array_append(v_fail, format('%s HELD-BACK school id(s) reached the catalog', v_n)); end if;

  select count(*) into v_n from public.statement_requirement_sets
   where verification_status not in ('unverified','needs-review','verified','conflicting');
  if v_n <> 0 then v_fail := array_append(v_fail, format('%s unexpected verification_status', v_n)); end if;
  select count(*) into v_n from public.statement_requirements
   where document_type not in ('personal-statement', 'goal-statement', 'diversity-statement', 'writing-sample', 'additional-response', 'other', 'statement-of-purpose', 'autobiographical-essay', 'supplemental-essay');
  if v_n <> 0 then v_fail := array_append(v_fail, format('%s unsupported document_type', v_n)); end if;

  select count(*) into v_n from public.statement_requirements
   where coalesce(words_enforcement, pages_enforcement, characters_enforcement) is not null
     and (coalesce(words_enforcement, 'enforced') not in ('truncated', 'enforced', 'target', 'suggested', 'unknown')
       or coalesce(characters_enforcement, 'enforced') not in ('truncated', 'enforced', 'target', 'suggested', 'unknown')
       or coalesce(pages_enforcement, 'enforced') not in ('truncated', 'enforced', 'target', 'suggested', 'unknown'));
  if v_n <> 0 then v_fail := array_append(v_fail, format('%s invalid enforcement category', v_n)); end if;

  -- truncation needs a maximum, in the unit that is truncated
  select count(*) into v_n from public.statement_requirements
   where (words_enforcement = 'truncated' and max_words is null)
      or (characters_enforcement = 'truncated' and max_characters is null)
      or (pages_enforcement = 'truncated' and max_pages is null);
  if v_n <> 0 then v_fail := array_append(v_fail, format('%s truncated register(s) with no maximum', v_n)); end if;

  -- unenforced_length never beside a bound, and the flag never without text
  select count(*) into v_n from public.statement_requirements
   where unenforced_length is not null
     and (min_words is not null or max_words is not null
       or min_characters is not null or max_characters is not null
       or min_pages is not null or max_pages is not null);
  if v_n <> 0 then v_fail := array_append(v_fail, format('%s row(s) carry unenforced_length beside a numeric bound', v_n)); end if;
  select count(*) into v_n from public.statement_requirements
   where unenforced_length_verbatim is not null and unenforced_length is null;
  if v_n <> 0 then v_fail := array_append(v_fail, format('%s row(s) carry the verbatim flag with no text', v_n)); end if;

  -- the two values this import exists to carry exactly
  select count(*) into v_n from public.statement_requirements where max_pages = 1.5;
  if v_n <> 2 then
    v_fail := array_append(v_fail, format('%s row(s) carry max_pages = 1.5, expected 2', v_n));
  end if;
  select count(*) into v_n from public.statement_requirements where unenforced_length is not null;
  if v_n <> 11 then
    v_fail := array_append(v_fail, format('%s row(s) carry unenforced_length, expected 11', v_n));
  end if;

  if array_length(v_fail, 1) is not null then
    raise exception E'IMPORT ROLLED BACK. % postcondition(s) failed:
  - %',
      array_length(v_fail, 1), array_to_string(v_fail, E'
  - ');
  end if;
  raise notice 'postconditions passed: 63 sets and 80 documents imported, all inactive';
end
$postcond$;

commit;

-- Nothing below this line. Activation and the rollout flags are separate
-- owner decisions and are deliberately not expressible in this file.
